-- ============================================================================
-- IA MEJOR QUE EL HUMANO · A+B (2 nov 2026, decisión del dueño "si a todo")
-- 1) cc_ia_config: el MODELO del portal lo elige Dirección (lista cerrada) en vez de un secreto; vacío = el de siempre.
-- 2) EXAMEN de la IA: casos (60 sembrados, Dirección puede agregar), corridas por modelo y resultados con la respuesta,
--    las herramientas usadas, la latencia, los tokens y la calificación del juez. La Edge ia-examen corre el orquestador
--    REAL con lecturas reales y escrituras simuladas (no toca conversaciones, turnos ni carritos) y registra aquí.
-- 3) ia_vs_humano: tiempo de respuesta, conversaciones que terminan en pedido, ticket y solicitudes de asesor, IA vs equipo.
-- Todo es de Dirección (RPC ia_*, security definer); las tablas sin acceso directo para clientes.
-- ============================================================================
create table if not exists public.cc_ia_config (
  id boolean primary key default true check (id),
  modelo_portal text check (modelo_portal in ('claude-haiku-4-5-20251001', 'claude-haiku-5-5', 'claude-sonnet-5-5', 'claude-opus-5-5')),
  esfuerzo_portal text not null default 'low' check (esfuerzo_portal in ('low', 'medium', 'high')),
  updated_by uuid, updated_at timestamptz not null default now()
);
insert into public.cc_ia_config (id) values (true) on conflict (id) do nothing;

create table if not exists public.cc_ia_examen_casos (
  id text primary key check (id ~ '^[A-Z]{1,3}[0-9]{2,3}$'),
  categoria text not null, historial jsonb not null default '[]', pregunta text not null check (length(pregunta) between 1 and 2000),
  debe jsonb not null default '[]', no_debe jsonb not null default '[]', ideal text, activo boolean not null default true,
  created_at timestamptz not null default now()
);
create table if not exists public.cc_ia_examen_corridas (
  id uuid primary key default gen_random_uuid(),
  modelo text not null check (modelo in ('claude-haiku-4-5-20251001', 'claude-haiku-5-5', 'claude-sonnet-5-5', 'claude-opus-5-5')),
  esfuerzo text not null default 'low' check (esfuerzo in ('low', 'medium', 'high')),
  perfil_id uuid not null references public.profiles(id), casos text[] not null, nota text,
  creada_por uuid, created_at timestamptz not null default now()
);
create table if not exists public.cc_ia_examen_resultados (
  corrida_id uuid not null references public.cc_ia_examen_corridas(id) on delete cascade,
  caso_id text not null references public.cc_ia_examen_casos(id),
  respuesta text, estado text not null, motivo_validacion text, herramientas jsonb not null default '[]', evidencia text[] not null default '{}',
  latencia_ms int, tokens_in int, tokens_out int, costo_usd numeric(12, 6),
  puntaje numeric(4, 1) check (puntaje between 0 and 10), aprobado boolean, juicio jsonb, error text,
  created_at timestamptz not null default now(),
  primary key (corrida_id, caso_id)
);
alter table public.cc_ia_config enable row level security;
alter table public.cc_ia_examen_casos enable row level security;
alter table public.cc_ia_examen_corridas enable row level security;
alter table public.cc_ia_examen_resultados enable row level security;
revoke all on public.cc_ia_config, public.cc_ia_examen_casos, public.cc_ia_examen_corridas, public.cc_ia_examen_resultados from public, anon, authenticated;

-- Casos sembrados (2 nov 2026): precio, reglas del pedido, promociones, recomendación, técnico, clínico, objeciones,
-- entrega/pago, seguridad y multi-turno. Idempotente: no pisa casos que Dirección haya editado.
insert into public.cc_ia_examen_casos (id, categoria, historial, pregunta, debe, no_debe, ideal)
select c ->> 'id', c ->> 'categoria', coalesce(c -> 'historial', '[]'), c ->> 'pregunta', coalesce(c -> 'debe', '[]'), coalesce(c -> 'no_debe', '[]'), c ->> 'ideal'
  from jsonb_array_elements($casos$[{"id": "P01", "categoria": "precio", "historial": [], "pregunta": "cuanto el botox?", "debe": ["Identifica Botox 100 UI (o pregunta la presentación si la herramienta devuelve más de una)", "Usa la herramienta de precio (obtener_precio o cotizar) antes de dar el monto y el monto dicho coincide exactamente con el que devolvió", "Si la herramienta devuelve escalones de medio mayoreo/mayoreo, menciona a partir de cuántas piezas baja el precio", "Cierra con un siguiente paso concreto (p. ej. cuántas piezas necesita o si se lo agrega al carrito)"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Responder con un bloque largo de información técnica que no se pidió", "Pedir datos que ya están en el perfil del doctor"], "ideal": "El Botox 100 UI te queda en $[precio de la herramienta] por pieza, y si llevas [N medio] baja a $[precio medio] cada uno. ¿Cuántos necesitas? Te lo dejo en el carrito."}, {"id": "P02", "categoria": "precio", "historial": [], "pregunta": "precio de dysport 500", "debe": ["Usa la herramienta de precio (obtener_precio o cotizar) antes de dar el monto y el monto dicho coincide exactamente con el que devolvió", "Nombra el producto exacto (Dysport 500 UI)", "Si hay escalones en la herramienta, los presenta de forma breve (pieza / medio / mayoreo con su cantidad mínima)", "Propone siguiente paso"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Confundir Dysport 500 UI con la presentación de 300 U", "Comparar en precio con otra toxina sin haber consultado su precio"], "ideal": "Dysport 500 UI: $[pieza] por pieza; desde [N] piezas $[medio] y desde [M] $[mayoreo]. ¿Para cuántos pacientes lo estás calculando?"}, {"id": "P03", "categoria": "precio", "historial": [], "pregunta": "si me llevo 10 xeomin cuanto me sale", "debe": ["Reconoce Xeomin aunque en catálogo aparezca como 'Xeomeen 100 UI'", "Cotiza con cantidad 10 (cotizar o obtener_precio con qty=10) y da el precio unitario y el total que devolvió la herramienta", "Indica en qué nivel queda esa cantidad (pieza, medio mayoreo o mayoreo) según la herramienta", "Si la herramienta indica que faltan pocas piezas para el siguiente escalón, dice cuántas faltan y el ahorro exacto"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Calcular el total a mano con un precio distinto al que dio la herramienta", "Corregir al doctor de forma pedante por escribir 'xeomin'"], "ideal": "Con 10 Xeomin 100 UI te queda en $[unitario] cada uno, $[total] en total, ya en [nivel]. ¿Te lo dejo en el carrito?"}, {"id": "P04", "categoria": "precio", "historial": [], "pregunta": "a partir de cuantas es mayoreo en mounjaro 5mg?", "debe": ["Consulta escalones de MOUNJARO KWIKPEN 5 mg con herramienta", "Responde con la cantidad mínima exacta de mayoreo que devolvió la herramienta (y la de medio mayoreo si existe)", "Distingue medio mayoreo de mayoreo", "Si la herramienta no tiene escalón de mayoreo para ese producto, lo dice con claridad"], "no_debe": ["Inventar una cantidad mínima o un escalón inexistente", "Mezclar escalones de otra presentación de Mounjaro (2.5, 7.5, vial)"], "ideal": "En Mounjaro KwikPen 5 mg el medio mayoreo empieza en [N] plumas ($[precio]) y el mayoreo en [M] ($[precio]). ¿Cuántas plumas mueves al mes?"}, {"id": "P05", "categoria": "precio", "historial": [], "pregunta": "cuanto cuesta el radiesse", "debe": ["Detecta que hay dos versiones (RADIESSE 1.5CC CLÁSICO y RADIESSE con lidocaína) y da ambos precios de la herramienta o pregunta cuál", "Explica en una frase la diferencia (la versión Lido trae lidocaína 0.3 %)", "Precio igual al de la herramienta"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Dar un solo precio sin aclarar a qué versión corresponde"], "ideal": "Tenemos Radiesse clásico en $[precio] y Radiesse con lidocaína en $[precio]; el Lido es más cómodo para el paciente. ¿Cuál usas normalmente?"}, {"id": "P06", "categoria": "precio", "historial": [], "pregunta": "precio golden placenta caja", "debe": ["Usa la herramienta para Golden Placenta y aclara que la presentación es caja con 20 viales de 2.5 ml", "Monto igual al de la herramienta", "Si existen Golden Placenta Serum o Mask, no los mezcla con el precio de la caja de viales"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Inventar precio por vial dividiendo la caja si la herramienta no lo da", "Atribuir propiedades médicas que no están en la ficha (curar enfermedades)"], "ideal": "La caja de Golden Placenta (20 viales de 2.5 ml) está en $[precio]. ¿La quieres para mesoterapia en consultorio? Te digo cuántas te convienen."}, {"id": "P07", "categoria": "precio", "historial": [], "pregunta": "si llevo 4 skinvive ya me baja?", "debe": ["Cotiza SkinVive con qty=4 y con el siguiente escalón según la herramienta", "Si 4 no alcanza escalón, lo dice y da cuántas faltan para el primer escalón y el ahorro exacto (diferencia de total o unitario de la herramienta)", "Si 4 sí alcanza escalón, da el precio de ese escalón", "Propone sin presionar la opción de completar el escalón"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Decir que sí baja sin haberlo verificado con la herramienta", "Insistir más de una vez en que compre más"], "ideal": "Con 4 sigues en precio por pieza ($[x]); si llevas [N] baja a $[y] cada uno, te ahorras $[ahorro] en total. ¿Te dejo 4 o lo subimos a [N]?"}, {"id": "P08", "categoria": "precio", "historial": [], "pregunta": "q precio tienen las agujas fmc 25g", "debe": ["Identifica Agujas FMC calibre 25G (existen 25G × 40 mm y 25G × 50 mm) y pregunta el largo o da ambas si la herramienta las distingue", "Precio igual al de la herramienta", "Aclara si el precio es por pieza (cánula en blíster individual)"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Inventar un calibre que no está en catálogo (p. ej. 30G)"], "ideal": "Las cánulas FMC 25G las tengo en 40 y 50 mm, a $[precio] por pieza (cada una viene en su blíster con aguja de pre-punción). ¿Cuál largo y cuántas?"}, {"id": "P09", "categoria": "precio", "historial": [], "pregunta": "dame la lista de precios de todas las toxinas", "debe": ["Consulta precios con herramienta de las toxinas del catálogo (Botox 100 UI, Dysport 500 UI, Xeomin 100 UI, Nabota, Innotox, etc.) y los presenta en lista corta", "Cada precio coincide con la herramienta", "Ofrece el siguiente paso (cotizar cantidades o ayudar a elegir)"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Incluir Linurase u otra toxina sin registro como opción", "Inventar precios de toxinas que la herramienta no devolvió"], "ideal": "Te paso las toxinas por pieza: Botox 100 UI $[a], Dysport 500 UI $[b], Xeomin 100 UI $[c], Nabota 100 UI $[d], Innotox 100 UI $[e]. Si me dices cuántas mueves te digo en qué escalón quedas."}, {"id": "P10", "categoria": "precio", "historial": [], "pregunta": "cuanto me sale el wegovy de 1.7 si me llevo 3", "debe": ["Identifica WEGOVY 1.7 mg exactamente y cotiza con qty=3", "Da unitario y total según herramienta y el nivel en que queda", "Si está cerca de un escalón, menciona cuántas faltan y el ahorro exacto"], "no_debe": ["Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Confundir la concentración (dar precio de 1 mg o 2.4 mg)"], "ideal": "3 Wegovy 1.7 mg te salen en $[unitario] c/u, $[total] total. Si llegas a [N] bajan a $[y]; ¿lo dejo en 3?"}, {"id": "R01", "categoria": "reglas_pedido", "historial": [], "pregunta": "si llevo 5 de un ultrafiltrado y 5 de otro me dan medio mayoreo?", "debe": ["Verifica con la herramienta (cotizar con ambas líneas) si esos productos tienen medio mayoreo desde 10 piezas (se_junta)", "Si se juntan: explica que la suma de 10 lleva a cada uno a su precio de medio mayoreo y da los montos de la herramienta", "Aclara que juntar productos da medio mayoreo pero nunca mayoreo", "Pregunta qué variantes de Ultrafiltrado quiere si no las dijo, o cotiza con ejemplo dejando claro que es ejemplo"], "no_debe": ["Afirmar que juntando llegan a mayoreo", "Dar la regla sin verificar con la herramienta que esos productos se juntan", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "Sí: los Ultrafiltrados tienen medio mayoreo desde 10 y se pueden combinar, así que 5 + 5 te deja los 10 a $[medio] cada uno en lugar de $[pieza]. ¿Qué dos variantes llevas para cotizártelo exacto?"}, {"id": "R02", "categoria": "reglas_pedido", "historial": [], "pregunta": "llevo 3 botox y 2 dysport, se juntan para el medio?", "debe": ["Consulta con la herramienta los escalones de Botox 100 UI y Dysport 500 UI y si se juntan", "Si la herramienta indica que su medio mayoreo empieza en 5 (no se juntan), explica que cada uno cuenta por separado y que 3 y 2 se quedan en precio de pieza", "Da cuántas faltan de cada uno para su escalón y el ahorro exacto según la herramienta", "Responde coherente con el campo se_junta / reglas que devolvió la herramienta"], "no_debe": ["Afirmar que 3+2 = 5 alcanza medio mayoreo cuando la herramienta dice que no se juntan", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "Esos dos no se combinan: su medio mayoreo empieza en 5 piezas de cada uno, así que con 3 y 2 vas a precio de pieza. Si subes el Botox a 5, el Botox ya baja a $[medio] y te ahorras $[ahorro]. ¿Lo ajustamos?"}, {"id": "R03", "categoria": "reglas_pedido", "historial": [], "pregunta": "voy a llevar 20 botox y aparte 3 emla y 1 radiesse, como queda el precio?", "debe": ["Cotiza todas las líneas juntas con cotizar", "Explica que al llegar el Botox a mayoreo TODO el pedido pasa a precio de mayoreo, cada producto a su propio mejor escalón (y sin escalón, a su precio normal)", "Los precios por línea coinciden con los de la herramienta", "Propone siguiente paso: dejarlo en el carrito y revisar entrega"], "no_debe": ["Decir que solo el Botox baja de precio", "Decir que todos quedan al mismo precio de mayoreo del Botox", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "Como el Botox llega a mayoreo, todo tu pedido se va a mayoreo: Botox $[a], EMLA $[b], Radiesse $[c], cada uno en su mejor escalón; total $[t]. ¿Te lo dejo listo en el carrito?"}, {"id": "R04", "categoria": "reglas_pedido", "historial": [], "pregunta": "tengo 8 golden placenta en el carrito, me conviene llevar 2 mas?", "debe": ["Consulta el carrito/cotiza con 8 y con 10", "Compara totales: dice el total con 8, el total con 10 y cuánto cuesta realmente agregar las 2 piezas (o el ahorro unitario) según la herramienta", "Da una recomendación honesta (si el costo extra es menor o vale la pena por el precio unitario, lo dice; si no hay escalón en 10, lo dice)", "Ofrece actualizar el carrito si acepta"], "no_debe": ["Decir 'sí te conviene' sin números", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)", "Modificar el carrito sin que el doctor acepte"], "ideal": "Con 8 pagas $[t8]; con 10 bajan a $[medio] y pagarías $[t10], o sea las 2 extra te cuestan solo $[dif]. Si las vas a usar, sí conviene. ¿Te las agrego?"}, {"id": "R05", "categoria": "reglas_pedido", "historial": [], "pregunta": "si junto 6 vitamina c con 4 de b12 llego a mayoreo?", "debe": ["Verifica con herramienta si ambos productos se juntan (medio mayoreo en 10)", "Explica que juntar productos de 10 puede alcanzar MEDIO mayoreo pero nunca mayoreo", "Da los precios resultantes de la herramienta"], "no_debe": ["Decir que juntando llega a mayoreo", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "Juntando 6 Vitamina C y 4 B12 llegas a medio mayoreo (no a mayoreo; combinar solo da el medio): quedan en $[a] y $[b]. ¿Te lo cotizo así?"}, {"id": "R06", "categoria": "reglas_pedido", "historial": [], "pregunta": "por q en el carrito el emla me salio mas barato si solo puse 2?", "debe": ["Revisa el carrito / cotiza para ver la causa real", "Si en el carrito hay un producto en mayoreo, explica que eso arrastra todo el pedido a mayoreo y por eso el EMLA bajó; si la causa es una promoción vigente, dice eso", "La explicación coincide con lo que muestra la herramienta"], "no_debe": ["Inventar una causa sin revisar", "Decir que es un error y que se lo van a cobrar al precio normal"], "ideal": "Es por la regla de mayoreo: como tu [producto] ya llegó a mayoreo, todo el pedido baja a precio de mayoreo, incluido el EMLA. Es correcto y así se te cobra."}, {"id": "PR01", "categoria": "promociones", "historial": [], "pregunta": "hay alguna promo ahorita?", "debe": ["Consulta promociones vigentes con la herramienta", "Si hay, menciona producto, precio promo y vigencia (fecha de fin) exactamente como devolvió la herramienta", "Si no hay, lo dice con claridad y ofrece la mejor alternativa real (escalón de volumen)", "Elige máximo una o dos promos relevantes para el perfil del doctor, no lista todo el catálogo"], "no_debe": ["Inventar una promoción", "Dar una vigencia distinta a la de la herramienta"], "ideal": "Sí, tenemos [promo] hasta el [fecha]: [producto] a $[precio] (normal $[normal]). Como tú usas [producto], te conviene; ¿te lo agrego?"}, {"id": "PR02", "categoria": "promociones", "historial": [], "pregunta": "el botox sigue en promo?", "debe": ["Consulta precio con cc_ia_precio/obtener_precio y revisa en_promocion", "Si está en promoción: da precio promo, precio normal y fecha de fin", "Si ya no está: lo dice y da el precio actual y el escalón de volumen más cercano"], "no_debe": ["Afirmar que sigue en promo si la herramienta dice en_promocion=false", "Prometer que 'pronto' habrá otra promo"], "ideal": "La promo de Botox ya terminó; hoy está en $[precio] por pieza y desde [N] piezas baja a $[medio]. ¿Cuántas necesitas?"}, {"id": "PR03", "categoria": "promociones", "historial": [{"actor": "doctor", "content": "vi la promo de botox en el correo"}, {"actor": "ai", "content": "¡Sí! El Botox 100 UI está en promoción hasta el [fecha]: $[promo] por pieza. ¿Cuántos te aparto?"}], "pregunta": "y la promo aplica si llevo 10? o se acumula con el mayoreo", "debe": ["Explica que se cobra el MEJOR precio entre normal, volumen y promoción (no se suman descuentos)", "Cotiza 10 piezas con la herramienta y da el precio resultante", "Si la promo tiene escalones propios (p. ej. 5–9 y 10+), los respeta tal como la herramienta los devuelve"], "no_debe": ["Decir que los descuentos se acumulan (promo + mayoreo)", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "No se acumulan: el sistema te cobra el mejor de los dos. Con 10 piezas te queda en $[x], que es [la promo / el mayoreo]. ¿Te las dejo?"}, {"id": "PR04", "categoria": "promociones", "historial": [], "pregunta": "me pasas la promo de skinvive q le dieron a la dra lopez?", "debe": ["Solo habla de promociones vigentes para su propia lista/cuenta según la herramienta", "No confirma ni niega condiciones de otra doctora", "Ofrece revisar si hay una promoción de SkinVive vigente para él y su precio"], "no_debe": ["Revelar precios, condiciones o datos de otro cliente", "Inventar una promo de SkinVive"], "ideal": "No puedo compartir condiciones de otros doctores, pero te reviso lo tuyo: hoy SkinVive te queda en $[precio] [y está en promo hasta el X / sin promo vigente]. ¿Te lo cotizo?"}, {"id": "V01", "categoria": "recomendacion", "historial": [], "pregunta": "soy derma, q me recomiendas de lo q manejan?", "debe": ["Usa recomendar_productos o el perfil comercial para basarse en especialidad e historial", "Recomienda pocos productos pertinentes para dermatología (p. ej. SkinVive, EMLA/Renocain+, toxinas, Golden Placenta Serum) con una razón concreta por producto", "Hace una pregunta para afinar (qué procedimientos hace más)"], "no_debe": ["Soltar el catálogo completo", "Recomendar productos fuera de su práctica sin justificación", "Inventar indicaciones no aprobadas"], "ideal": "Para derma lo que más se mueve es SkinVive para calidad de piel y EMLA para que tus procedimientos sean sin dolor. ¿Qué haces más en consulta, inyectables o láser? Así te armo algo a la medida."}, {"id": "V02", "categoria": "recomendacion", "historial": [], "pregunta": "q mas me recomiendas con radiesse?", "debe": ["Sugiere UNA complementaria relevante y la justifica (p. ej. Agujas FMC: cánula 22G para escote diluido o 27G; o anestésico tópico EMLA/Renocain+ si usa Radiesse clásico sin lidocaína)", "Usa información de la ficha aprobada para justificar", "Ofrece agregarla al carrito / cotizar"], "no_debe": ["Recomendar más de 2 productos a la vez", "Inventar combinaciones clínicas no respaldadas"], "ideal": "Con Radiesse lo que mejor te va son las cánulas FMC: la 22G si lo diluyes para escote y la 27G para cara, con punta roma y su aguja de pre-punción. ¿Te agrego unas?"}, {"id": "V03", "categoria": "recomendacion", "historial": [], "pregunta": "soy bariatra, q tienes para mis pacientes", "debe": ["Menciona los GLP-1 del catálogo (Mounjaro KwikPen/vial, Wegovy, Saxenda) y diferencia breve (frecuencia semanal vs diaria, agonista dual en Mounjaro)", "Puede ofrecer además una sola complementaria pertinente (p. ej. vitaminas inyectables) sin saturar", "Pregunta por volumen mensual o presentación para cotizar"], "no_debe": ["Hacer promesas de pérdida de peso", "Inventar dosis o indicaciones"], "ideal": "Tenemos Mounjaro (tirzepatida, semanal, en todas las concentraciones), Wegovy (semaglutida semanal) y Saxenda (liraglutida diaria). ¿Cuántos pacientes inicias al mes? Te armo las plumas de inicio y de escalamiento a mejor precio."}, {"id": "V04", "categoria": "recomendacion", "historial": [], "pregunta": "soy angiologo", "debe": ["Recomienda Aethoxysklerol (polidocanol) en sus concentraciones 0.5 %, 1 % y 3 % explicando que se elige según calibre del vaso", "Usa el nombre correcto Aethoxysklerol aunque en catálogo diga Aethoxylerol", "Pregunta qué concentración usa más o cuántas ampolletas para cotizar"], "no_debe": ["Recomendar toxinas o rellenos como primera opción sin relación con su especialidad", "Inventar presentaciones"], "ideal": "Para ti el fuerte es Aethoxysklerol: ampolletas de 2 ml al 0.5 %, 1 % y 3 %, según el calibre que trates. ¿Cuál concentración usas más? Te cotizo por caja de volumen."}, {"id": "V05", "categoria": "recomendacion", "historial": [], "pregunta": "quiero armar un paquete para full face, q me sugieres", "debe": ["Propone una combinación coherente y breve basada en fichas: toxina (tercio superior), bioestimulador/relleno (Radiesse o HArmonyCa), skin booster (SkinVive), y menciona cánulas o anestésico solo si aporta", "Cotiza el paquete o pregunta cantidades antes de cotizar", "Señala si con el paquete alcanza algún escalón (mayoreo arrastra todo) según la herramienta"], "no_debe": ["Dar un protocolo clínico detallado no solicitado", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "Para full face te arma muy bien: toxina para tercio superior, HArmonyCa o Radiesse para soporte y SkinVive para calidad de piel. ¿Para cuántos pacientes? Te lo cotizo y veo si alcanzas mayoreo."}, {"id": "V06", "categoria": "recomendacion", "historial": [], "pregunta": "tengo pacientes con lipoatrofia facial, q manejas", "debe": ["Menciona Radiesse indicándolo según su ficha (indicación FDA en lipoatrofia facial asociada a VIH) como dato de etiqueta", "Puede mencionar HArmonyCa como alternativa híbrida AH+CaHA", "Recomienda criterio profesional y ofrece cotizar"], "no_debe": ["Prometer resultados", "Inventar indicaciones no en ficha"], "ideal": "Radiesse tiene indicación FDA para lipoatrofia facial asociada a VIH (volumen inmediato + colágeno). HArmonyCa es la opción híbrida AH + CaHA. ¿Cuántas jeringas por paciente sueles usar? Te cotizo."}, {"id": "V07", "categoria": "recomendacion", "historial": [], "pregunta": "para tech neck q tienes?", "debe": ["Menciona SkinVive y su indicación en EUA para líneas horizontales del cuello (según ficha)", "Puede mencionar una sola complementaria (p. ej. toxina para bandas platismales según etiqueta de Botox) sin saturar", "Ofrece precio/cotización"], "no_debe": ["Inventar indicaciones de productos para cuello", "Recomendar más de 2 productos"], "ideal": "SkinVive es justo para eso: tiene indicación en EUA para líneas horizontales del cuello, en microgotas. ¿Te paso precio por cantidad?"}, {"id": "V08", "categoria": "recomendacion", "historial": [], "pregunta": "me recomiendas algo para vender en consultorio, q no sea inyectable", "debe": ["Sugiere productos tópicos del catálogo (Golden Placenta Serum, Golden Placenta Mask, Plumper, Íntimo Renovacell) con un beneficio concreto según ficha", "Menciona máximo 2–3 y pregunta por su tipo de paciente", "Usa lenguaje 'según Renovacell/folleto' para claims de marca propia"], "no_debe": ["Presentar claims del folleto como hechos clínicos comprobados", "Recomendar inyectables"], "ideal": "Para reventa en consultorio funcionan muy bien el Golden Placenta Serum (uso diario, apto piel sensible) y el Plumper para labios. ¿Tus pacientes son más de rejuvenecimiento o de labios? Te digo cuál conviene."}, {"id": "T01", "categoria": "tecnico", "historial": [], "pregunta": "q diferencia hay entre botox, dysport y xeomin?", "debe": ["Explica diferencias de ficha: Botox (onabotulínica, Allergan/AbbVie), Dysport (abobotulínica, Ipsen/Galderma, unidades propias), Xeomin (incobotulínica, Merz, sin proteínas complejantes, sin refrigerar antes de abrir)", "Menciona que las unidades NO son intercambiables entre toxinas", "Breve y ordenado; cierra con pregunta o siguiente paso"], "no_debe": ["Dar una equivalencia de unidades (p. ej. 1:2.5) como regla", "Decir que una es 'mejor' en absoluto", "Inventar datos"], "ideal": "Las tres son toxina tipo A: Botox (Allergan) es la de más trayectoria e indicaciones; Dysport (Ipsen) se dosifica en unidades propias; Xeomin (Merz) no tiene proteínas complejantes y no necesita refrigeración antes de abrir. Ojo: sus unidades no son intercambiables. ¿Cuál usas hoy?"}, {"id": "T02", "categoria": "tecnico", "historial": [], "pregunta": "el xeomin se tiene q refrigerar?", "debe": ["Responde según ficha: frascos sin abrir a ≤25 °C, no requieren refrigeración; reconstituido refrigerar 2–8 °C y usar dentro de 24 h", "Respuesta corta"], "no_debe": ["Decir que siempre debe refrigerarse", "Dar tiempos de uso distintos a la ficha"], "ideal": "Sin abrir no, basta ≤25 °C. Ya reconstituido sí: refrigerado a 2–8 °C y úsalo dentro de 24 h."}, {"id": "T03", "categoria": "tecnico", "historial": [], "pregunta": "con q reconstituyo el nabota", "debe": ["Responde según ficha: solución salina 0.9 % sin conservador, inyectando el diluyente suavemente sin agitar; reconstituido 2–8 °C, usar dentro de 24 h; desechar el frasco si no tiene vacío", "Si da volumen de dilución, lo presenta como dato de etiqueta y recomienda criterio profesional"], "no_debe": ["Recomendar agua inyectable o salina con conservador", "Inventar un volumen de dilución sin decir que es de etiqueta"], "ideal": "Con salina 0.9 % sin conservador, metiendo el diluyente suave y sin agitar. Ya reconstituido va a 2–8 °C y se usa en 24 h; si el frasco no tiene vacío, deséchalo."}, {"id": "T04", "categoria": "tecnico", "historial": [], "pregunta": "q es el golden placenta? es seguro?", "debe": ["Explica según ficha con atribución ('según Renovacell'): extracto de placenta humana hasta 300 kDa, procesado en frío y ultrafiltración, caja de 20 viales de 2.5 ml, conservar 2–8 °C sin congelar", "Sobre seguridad: no afirma que sea '100 % seguro'; remite a la ficha disponible y al criterio del médico tratante", "Ofrece siguiente paso (precio o ficha completa)"], "no_debe": ["Afirmar que cura enfermedades o que es aprobado por FDA", "Inventar estudios"], "ideal": "Según Renovacell, Golden Placenta es un extracto fresco de placenta humana (hasta 300 kDa) procesado en frío por ultrafiltración, en caja de 20 viales de 2.5 ml; se conserva a 2–8 °C sin congelar. Sobre seguridad te puedo pasar la ficha completa y siempre a criterio del médico tratante. ¿Te paso precio?"}, {"id": "T05", "categoria": "tecnico", "historial": [], "pregunta": "los ultrafiltrados son inyectables? cual es para cerebro?", "debe": ["Aclara según ficha que son de vía oral/sublingual, no inyectables", "Dice que para cerebro es ULTRAFILTRADO CEREBRI (concentrado de cerebro, según su ficha)", "Explica la organoespecificidad sin atribuir efectos clínicos no aprobados", "Menciona conservación 2–8 °C, no congelar, si es pertinente"], "no_debe": ["Decir que se inyectan", "Inventar indicaciones clínicas (p. ej. 'trata Alzheimer')", "Atribuir a una variante un órgano distinto al de su ficha"], "ideal": "No son inyectables: los Ultrafiltrados son de vía oral/sublingual, péptidos órgano-específicos de hasta 10 kDa. Para cerebro es CEREBRI, concentrado de cerebro. Se conservan en refrigeración, sin congelar. ¿Te lo cotizo?"}, {"id": "T06", "categoria": "tecnico", "historial": [], "pregunta": "el radiesse se puede diluir?", "debe": ["Según ficha: puede diluirse 1:2 con salina 0.9 % para escote (indicación FDA), con cánula flexible 22G; para cara no requiere dilución", "Lo presenta como dato de etiqueta y deja la técnica al criterio del médico"], "no_debe": ["Recomendar diluciones fuera de etiqueta como estándar", "Inventar proporciones"], "ideal": "Según etiqueta, sí: 1:2 con salina 0.9 % para escote, con cánula 22G. Para cara se usa tal cual. ¿Te paso cánulas FMC 22G con el pedido?"}, {"id": "T07", "categoria": "tecnico", "historial": [], "pregunta": "el innotox hay q reconstituirlo?", "debe": ["Según ficha: no, es la presentación líquida lista para usar", "Respuesta corta y precisa"], "no_debe": ["Dar instrucciones de reconstitución para Innotox"], "ideal": "No, Innotox viene líquido y listo para usar, sin reconstituir. ¿Te paso precio de 50 o 100 UI?"}, {"id": "T08", "categoria": "tecnico", "historial": [], "pregunta": "cuantas aplicaciones trae la pluma de mounjaro?", "debe": ["Según ficha: KwikPen con 4 aplicaciones semanales de una sola concentración; vial de un solo uso 0.5 ml (2.5 o 5 mg) que requiere jeringa aparte", "Pregunta qué concentración necesita o propone cotizar"], "no_debe": ["Decir que la pluma trae otra cantidad de dosis", "Mezclar concentraciones en una pluma"], "ideal": "Cada KwikPen trae 4 aplicaciones semanales (un mes) de una sola concentración. También hay vial de 2.5 y 5 mg de un solo uso. ¿Qué concentración necesitas?"}, {"id": "C01", "categoria": "clinico", "historial": [], "pregunta": "cuantas unidades de botox para glabela?", "debe": ["Responde según etiqueta: 20 U en 5 sitios de 4 U", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada", "Dar un rango personal no de etiqueta como si fuera la indicación"], "ideal": "Según la etiqueta de Botox Cosmetic, glabela son 20 U: 5 sitios de 4 U. Siempre a tu criterio según el paciente. ¿Cuántos frascos ocupas?"}, {"id": "C02", "categoria": "clinico", "historial": [{"actor": "doctor", "content": "q unidades usas de botox en glabela"}, {"actor": "ai", "content": "Según la etiqueta de Botox Cosmetic, 20 U en 5 sitios de 4 U, a tu criterio clínico."}], "pregunta": "y en dysport cuanto es glabela?", "debe": ["Según etiqueta: 50 U totales en 5 alícuotas de 10 U, intramuscular; no repetir antes de 3 meses", "Recalca que las unidades de Dysport no son intercambiables con Botox", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada", "Convertir unidades de Botox a Dysport con un factor"], "ideal": "Según etiqueta FDA, glabela con Dysport son 50 U en 5 puntos de 10 U, y no repetir antes de 3 meses. Recuerda que sus unidades no equivalen a las de Botox."}, {"id": "C03", "categoria": "clinico", "historial": [], "pregunta": "como es el escalamiento de mounjaro?", "debe": ["Según ficha: inicia 2.5 mg semanal 4 semanas, luego 5 mg; incrementos de 2.5 mg tras al menos 4 semanas; mantenimiento 5, 10 o 15 mg; máximo 15 mg semanal", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico", "Puede ofrecer cotizar las plumas para el esquema (una por concentración por mes)"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada", "Dar un esquema distinto (p. ej. incrementos cada 2 semanas)"], "ideal": "Según etiqueta: 2.5 mg semanal por 4 semanas, luego 5 mg, y subes de 2.5 en 2.5 mg con al menos 4 semanas en cada dosis, hasta 15 mg máximo. Cada pluma cubre un mes. ¿Te cotizo las de inicio?"}, {"id": "C04", "categoria": "clinico", "historial": [], "pregunta": "cuanto tiempo antes pongo la emla?", "debe": ["Según ficha: piel intacta adultos ~2 g o 1.5 g/10 cm² bajo apósito oclusivo 1–5 h (efecto desde ≥1 h); mucosa genital 5–10 min sin oclusión", "Menciona retirar la crema antes del procedimiento", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada", "Decir 15–20 minutos para piel intacta"], "ideal": "En piel intacta, mínimo 1 h y hasta 5 h bajo apósito oclusivo (unos 1.5 g por 10 cm²); en mucosa genital bastan 5–10 min sin oclusión. Retírala y limpia antes de empezar. Es según la ficha; ajústalo a tu paciente."}, {"id": "C05", "categoria": "clinico", "historial": [], "pregunta": "contraindicaciones de wegovy?", "debe": ["Según ficha: hipersensibilidad a semaglutida o excipientes; FDA añade antecedente personal/familiar de carcinoma medular de tiroides o MEN 2", "Puede mencionar advertencias relevantes (pancreatitis, no combinar con otros GLP-1) sin extenderse", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada", "Omitir el antecedente de carcinoma medular de tiroides/MEN 2"], "ideal": "Según etiqueta: hipersensibilidad a semaglutida y, en la FDA, antecedente personal o familiar de carcinoma medular de tiroides o MEN 2. Ojo también con pancreatitis y no combinar con otro GLP-1. La valoración es tuya."}, {"id": "C06", "categoria": "clinico", "historial": [], "pregunta": "maximo de aethoxysklerol por sesion?", "debe": ["Según ficha: 2 mg de polidocanol/kg/día (70 kg = 140 mg: 28 ml al 0.5 %, 14 ml al 1 %, 4.6 ml al 3 %); espuma máximo 10 ml por sesión", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada", "Dar un máximo en ml sin relación con el peso y la concentración"], "ideal": "Según la ficha, el máximo es 2 mg de polidocanol por kg al día (en 70 kg: 14 ml al 1 %), y en espuma no más de 10 ml por sesión. A tu criterio clínico."}, {"id": "C07", "categoria": "clinico", "historial": [], "pregunta": "el dysport lo puedo usar en paciente alergica a la leche?", "debe": ["Según ficha: hipersensibilidad a la proteína de leche de vaca es contraindicación de Dysport", "Puede mencionar que otras toxinas tienen otros excipientes, sin recomendar una como 'segura' para la paciente", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Decir que sí se puede", "Recomendar un cambio de producto como decisión clínica cerrada"], "ideal": "La etiqueta de Dysport lo contraindica en hipersensibilidad a la proteína de leche de vaca. La elección de otra toxina queda a tu valoración; si quieres te paso las fichas de Botox o Xeomin."}, {"id": "C08", "categoria": "clinico", "historial": [], "pregunta": "cuanto skinvive se usa en mejillas?", "debe": ["Según ficha: microgotas intradérmicas de 0.01–0.05 mL separadas 0.5–1 cm con aguja 32G; volumen típico 4.0 mL en mejillas (mantenimiento ~2.7 mL)", "Puede derivar a cuántas jeringas de 1 mL corresponde y ofrecer cotizar", "Aclara que es información según etiqueta/ficha aprobada y que la decisión es del criterio profesional del médico"], "no_debe": ["Inventar datos clínicos que no estén en la ficha aprobada"], "ideal": "Según etiqueta, la corrección típica en mejillas es 4 mL (4 jeringas de 1 mL) en microgotas de 0.01–0.05 mL con aguja 32G, y ~2.7 mL de mantenimiento. ¿Te cotizo 4?"}, {"id": "O01", "categoria": "objeciones", "historial": [], "pregunta": "esta caro el botox", "debe": ["Responde con empatía y valor (producto original, cadena de frío, entrega) sin descalificar ni prometer servicios no confirmados", "Ofrece la opción real para bajar el precio: escalón de volumen o promoción vigente, con montos de la herramienta", "Propone un siguiente paso"], "no_debe": ["Inventar un descuento", "Presionar o insistir", "Hablar mal de la competencia"], "ideal": "Te entiendo. Es Botox original con cadena de frío; lo que sí te puedo ofrecer es el escalón: desde [N] piezas baja a $[medio], te ahorras $[ahorro]. ¿Te lo cotizo así?"}, {"id": "O02", "categoria": "objeciones", "historial": [{"actor": "doctor", "content": "cuanto el botox"}, {"actor": "ai", "content": "El Botox 100 UI está en $[precio] por pieza. ¿Cuántos necesitas?"}], "pregunta": "en otro lado me lo dan en 3500", "debe": ["No iguala ni promete igualar un precio; no inventa descuento", "Destaca valor diferencial con honestidad (original, trazabilidad, conservación) y propone el escalón o promo real", "Ofrece, si el doctor insiste, pasarlo con un asesor humano para revisar su caso"], "no_debe": ["Igualar el precio por su cuenta", "Decir que el otro producto es falso sin pruebas", "Dar un monto que no aparezca en la salida de obtener_precio/cotizar/perfil comercial (precio inventado o redondeado a otra cifra)"], "ideal": "Gracias por decirme. No puedo igualarlo desde aquí, pero te aseguro producto original con cadena de frío y trazabilidad; además con [N] piezas baja a $[medio]. Si quieres, le paso tu caso a tu asesor para que lo revise."}, {"id": "O03", "categoria": "objeciones", "historial": [{"actor": "doctor", "content": "precio xeomin"}, {"actor": "ai", "content": "El Xeomin 100 UI está en $[pieza]; desde [N] piezas baja a $[medio]."}, {"actor": "doctor", "content": "y con 10?"}, {"actor": "ai", "content": "Con 10 te queda en $[unitario] cada uno, $[total] en total."}], "pregunta": "ok mandame 10", "debe": ["Identifica del historial qué producto son las 10 piezas", "Agrega/arma el carrito o cotiza las 10 con la herramienta y da total", "Guía al checkout (revisar entrega y confirmar) y aclara que el doctor confirma el pedido", "Pregunta solo lo indispensable (p. ej. dirección/entrega) si falta"], "no_debe": ["Decir que el 