create or replace function public.ia_config() returns jsonb
  language plpgsql stable security definer set search_path = public as
$$
begin
  perform public._cc_exige_admin();
  return (select jsonb_build_object('modelo_portal', modelo_portal, 'esfuerzo_portal', esfuerzo_portal, 'updated_at', updated_at,
    'modelos', jsonb_build_array('claude-haiku-4-5-20251001', 'claude-haiku-5-5', 'claude-sonnet-5-5', 'claude-opus-5-5')) from public.cc_ia_config where id);
end;
$$;

create or replace function public.ia_config_guardar(p_modelo text, p_esfuerzo text default 'low') returns jsonb
  language plpgsql security definer set search_path = public as
$$
begin
  perform public._cc_exige_admin();
  update public.cc_ia_config set modelo_portal = nullif(btrim(p_modelo), ''), esfuerzo_portal = coalesce(nullif(btrim(p_esfuerzo), ''), 'low'),
         updated_by = auth.uid(), updated_at = now() where id;
  return public.ia_config();
end;
$$;

create or replace function public.ia_examen_crear(p_modelo text, p_perfil uuid, p_esfuerzo text default 'low', p_casos text[] default null, p_nota text default null) returns uuid
  language plpgsql security definer set search_path = public as
$$
declare v_id uuid; v_casos text[];
begin
  perform public._cc_exige_admin();
  if not exists (select 1 from public.profiles where id = p_perfil and role_id = 'doctor' and verified and active) then
    raise exception 'PERFIL_INVALIDO: el examen se corre como un doctor verificado y activo' using errcode = 'check_violation';
  end if;
  select array_agg(id order by id) into v_casos from public.cc_ia_examen_casos where activo and (p_casos is null or id = any (p_casos));
  if coalesce(array_length(v_casos, 1), 0) = 0 then raise exception 'SIN_CASOS' using errcode = 'check_violation'; end if;
  insert into public.cc_ia_examen_corridas (modelo, esfuerzo, perfil_id, casos, nota, creada_por)
  values (p_modelo, coalesce(p_esfuerzo, 'low'), p_perfil, v_casos, left(p_nota, 300), auth.uid()) returning id into v_id;
  return v_id;
end;
$$;

-- Para la Edge (service_role): la corrida y el caso a correr, en una lectura.
create or replace function public.ia_examen_caso(p_corrida uuid, p_caso text) returns jsonb
  language plpgsql stable security definer set search_path = public as
$$
begin
  perform public._cc_solo_servicio();
  return (select jsonb_build_object('modelo', r.modelo, 'esfuerzo', r.esfuerzo, 'perfil_id', r.perfil_id,
            'caso', to_jsonb(c) - 'created_at')
            from public.cc_ia_examen_corridas r join public.cc_ia_examen_casos c on c.id = p_caso
           where r.id = p_corrida and p_caso = any (r.casos));
end;
$$;

create or replace function public.ia_examen_registrar(p_corrida uuid, p_caso text, p_r jsonb) returns void
  language plpgsql security definer set search_path = public as
$$
begin
  perform public._cc_solo_servicio();
  insert into public.cc_ia_examen_resultados (corrida_id, caso_id, respuesta, estado, motivo_validacion, herramientas, evidencia, latencia_ms, tokens_in, tokens_out, costo_usd, puntaje, aprobado, juicio, error)
  values (p_corrida, p_caso, left(p_r ->> 'respuesta', 6000), coalesce(p_r ->> 'estado', 'error'), p_r ->> 'motivo_validacion', coalesce(p_r -> 'herramientas', '[]'),
          coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p_r -> 'evidencia', '[]')) x), '{}'),
          (p_r ->> 'latencia_ms')::int, (p_r ->> 'tokens_in')::int, (p_r ->> 'tokens_out')::int, (p_r ->> 'costo_usd')::numeric,
          (p_r ->> 'puntaje')::numeric, (p_r ->> 'aprobado')::boolean, p_r -> 'juicio', left(p_r ->> 'error', 500))
  on conflict (corrida_id, caso_id) do update set respuesta = excluded.respuesta, estado = excluded.estado, motivo_validacion = excluded.motivo_validacion,
    herramientas = excluded.herramientas, evidencia = excluded.evidencia, latencia_ms = excluded.latencia_ms, tokens_in = excluded.tokens_in, tokens_out = excluded.tokens_out,
    costo_usd = excluded.costo_usd, puntaje = excluded.puntaje, aprobado = excluded.aprobado, juicio = excluded.juicio, error = excluded.error, created_at = now();
end;
$$;

create or replace function public.ia_examen_corridas() returns jsonb
  language plpgsql stable security definer set search_path = public as
$$
begin
  perform public._cc_exige_admin();
  return coalesce((select jsonb_agg(x order by x ->> 'created_at' desc) from (
    select jsonb_build_object('id', r.id, 'modelo', r.modelo, 'esfuerzo', r.esfuerzo, 'nota', r.nota, 'created_at', r.created_at,
      'perfil', (select full_name from public.profiles where id = r.perfil_id),
      'casos', array_length(r.casos, 1), 'corridos', count(s.caso_id),
      'puntaje', round(avg(s.puntaje), 1), 'aprobados', count(*) filter (where s.aprobado),
      'rechazos_validacion', count(*) filter (where s.motivo_validacion is not null), 'errores', count(*) filter (where s.estado <> 'respondio'),
      'latencia_p50', percentile_cont(0.5) within group (order by s.latencia_ms), 'latencia_p90', percentile_cont(0.9) within group (order by s.latencia_ms),
      'costo_promedio_usd', round(avg(s.costo_usd), 5),
      'por_categoria', (select jsonb_object_agg(cat, p) from (select c.categoria cat, round(avg(s2.puntaje), 1) p from public.cc_ia_examen_resultados s2 join public.cc_ia_examen_casos c on c.id = s2.caso_id where s2.corrida_id = r.id group by 1) z)) x
      from public.cc_ia_examen_corridas r left join public.cc_ia_examen_resultados s on s.corrida_id = r.id
     group by r.id order by r.created_at desc limit 30) q), '[]'::jsonb);
end;
$$;

create or replace function public.ia_examen_resultados(p_corrida uuid) returns jsonb
  language plpgsql stable security definer set search_path = public as
$$
begin
  perform public._cc_exige_admin();
  return coalesce((select jsonb_agg(jsonb_build_object('caso_id', c.id, 'categoria', c.categoria, 'pregunta', c.pregunta, 'historial', c.historial, 'ideal', c.ideal,
      'respuesta', s.respuesta, 'estado', s.estado, 'motivo_validacion', s.motivo_validacion, 'herramientas', s.herramientas,
      'latencia_ms', s.latencia_ms, 'costo_usd', s.costo_usd, 'puntaje', s.puntaje, 'aprobado', s.aprobado, 'juicio', s.juicio, 'error', s.error) order by c.id)
    from public.cc_ia_examen_corridas r cross join lateral unnest(r.casos) k(id) join public.cc_ia_examen_casos c on c.id = k.id
    left join public.cc_ia_examen_resultados s on s.corrida_id = r.id and s.caso_id = c.id
    where r.id = p_corrida), '[]'::jsonb);
end;
$$;

-- IA vs EQUIPO en conversaciones reales: quién responde y qué tan rápido, y qué pasa con la conversación.
create or replace function public.ia_vs_humano(p_dias int default 30) returns jsonb
  language plpgsql stable security definer set search_path = public as
$$
declare v_desde timestamptz := now() - make_interval(days => least(greatest(coalesce(p_dias, 30), 1), 365));
begin
  perform public._cc_exige_admin();
  return (with cliente as (
      select m.conversation_id, m.seq, m.created_at from public.cc_messages m
       where m.created_at >= v_desde and m.actor_type in ('doctor', 'visitor')),
    resp as (
      select c.conversation_id, c.created_at, r.actor_type quien, extract(epoch from r.created_at - c.created_at) seg
        from cliente c cross join lateral (select m.actor_type, m.created_at from public.cc_messages m
          where m.conversation_id = c.conversation_id and m.seq > c.seq and m.actor_type in ('ai', 'seller', 'admin', 'doctor', 'visitor') order by m.seq limit 1) r
       where r.actor_type in ('ai', 'seller', 'admin')),
    conv as (
      select v.id, v.profile_id, v.asesoria_solicitada_at,
             exists (select 1 from public.cc_messages m where m.conversation_id = v.id and m.actor_type in ('seller', 'admin')) con_humano,
             exists (select 1 from public.cc_messages m where m.conversation_id = v.id and m.actor_type = 'ai') con_ia,
             (select max(m.created_at) from public.cc_messages m where m.conversation_id = v.id) ultimo,
             (select o.total from public.cc_carts k join public.orders o on o.id = k.converted_order_id where k.conversation_id = v.id and k.converted_order_id is not null order by o.created_at desc limit 1) pedido_carrito
        from public.cc_conversations v where v.last_message_at >= v_desde),
    conv2 as (
      select c.*, coalesce(c.pedido_carrito, (select o.total from public.orders o where o.doctor_id = c.profile_id and o.created_at between c.ultimo - interval '1 day' and c.ultimo + interval '7 days' order by o.created_at limit 1)) pedido,
             case when c.con_humano then 'equipo' when c.con_ia then 'ia' else 'sin_respuesta' end atendio
        from conv c)
    select jsonb_build_object('dias', p_dias,
      'respuestas', (select coalesce(jsonb_object_agg(q, x), '{}'::jsonb) from (select case when quien = 'ai' then 'ia' else 'equipo' end q,
          jsonb_build_object('n', count(*), 'mediana_seg', round(percentile_cont(0.5) within group (order by seg)::numeric), 'p90_seg', round(percentile_cont(0.9) within group (order by seg)::numeric),
                             'en_5_min', round(100.0 * count(*) filter (where seg <= 300) / count(*), 1)) x from resp group by 1) z),
      'conversaciones', (select coalesce(jsonb_object_agg(atendio, x), '{}'::jsonb) from (select atendio, jsonb_build_object('n', count(*),
          'con_pedido', count(*) filter (where pedido is not null), 'conversion', round(100.0 * count(*) filter (where pedido is not null) / nullif(count(*), 0), 1),
          'ticket_promedio', round(avg(pedido)::numeric, 0), 'pidieron_asesor', count(*) filter (where asesoria_solicitada_at is not null)) x from conv2 group by 1) z),
      'muestra_suficiente', (select count(*) >= 30 from resp)));
end;
$$;

do $g$ begin
  execute 'revoke all on function public.ia_config(), public.ia_config_guardar(text, text), public.ia_examen_crear(text, uuid, text, text[], text), public.ia_examen_caso(uuid, text), public.ia_examen_registrar(uuid, text, jsonb), public.ia_examen_corridas(), public.ia_examen_resultados(uuid), public.ia_vs_humano(int) from public, anon';
  execute 'grant execute on function public.ia_config(), public.ia_config_guardar(text, text), public.ia_examen_crear(text, uuid, text, text[], text), public.ia_examen_corridas(), public.ia_examen_resultados(uuid), public.ia_vs_humano(int) to authenticated';
  execute 'revoke all on function public.ia_examen_caso(uuid, text), public.ia_examen_registrar(uuid, text, jsonb) from authenticated';
  execute 'grant execute on function public.ia_examen_caso(uuid, text), public.ia_examen_registrar(uuid, text, jsonb) to service_role';
end $g$;
